import { unstable_cache } from 'next/cache';

// Mock database
let products = [
  { id: '1', name: 'Product A', price: 100, stock: 50 },
  { id: '2', name: 'Product B', price: 200, stock: 20 },
  { id: '3', name: 'Product C', price: 300, stock: 0 },
];

// Simulate external update
export async function updateCatalogSource() {
  // In a real app, this would trigger an ERP sync or update the DB
  // Here we just modify our in-memory data to prove the sync happened
  products = products.map(p => ({
    ...p,
    price: p.price + 1, // Increment price to show change
    stock: Math.floor(Math.random() * 100)
  }));
  console.log('Catalog source updated');
}

// Cached data fetcher
export const getProducts = unstable_cache(
  async () => {
    console.log('Fetching products from source (slow)...');
    await new Promise((resolve) => setTimeout(resolve, 2000)); // Simulate slow DB/ERP fetch
    return products;
  },
  ['products'], // Key parts
  { tags: ['products'] } // Cache tags
);

