import { getProducts, syncProducts } from '@/lib/data';

export default async function ProductsPage() {
  const products = await getProducts();
  const timestamp = new Date().toLocaleTimeString();

  async function sync() {
    'use server';
    // Trigger sync without blocking
    // In a real production environment, you might use a queue or `after`
    // to ensure the process completes.
    syncProducts().catch(console.error);
  }

  return (
    <div className="p-8 font-sans">
      <h1 className="text-2xl font-bold mb-4">Product Catalog (Admin)</h1>
      <p className="text-sm text-gray-500 mb-6">Last rendered: {timestamp}</p>

      <div className="mb-8">
        <form action={sync}>
          <button 
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
          >
            Sync Latest Catalog
          </button>
          <p className="text-xs text-gray-500 mt-2">
            Triggers background refresh. Updates may take a few seconds to appear.
          </p>
        </form>
      </div>

      <div className="border rounded-lg overflow-hidden">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">ID</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Name</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Price</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Stock</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {products.map((product) => (
              <tr key={product.id}>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{product.id}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{product.name}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">${product.price}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{product.stock}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

