import { unstable_cache, revalidateTag } from 'next/cache';
import fs from 'fs';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'products.json');

// Initialize mock database if not exists
if (!fs.existsSync(DB_PATH)) {
  const initialProducts = [
    { id: '1', name: 'Product A', price: 100, stock: 50 },
    { id: '2', name: 'Product B', price: 200, stock: 20 },
    { id: '3', name: 'Product C', price: 300, stock: 0 },
  ];
  fs.writeFileSync(DB_PATH, JSON.stringify(initialProducts));
}

// Helper to read/write (synchronous for simplicity in mock)
function readDB() {
  try {
    return JSON.parse(fs.readFileSync(DB_PATH, 'utf-8'));
  } catch (e) {
    return [];
  }
}

function writeDB(data: any) {
  fs.writeFileSync(DB_PATH, JSON.stringify(data));
}

// Cached data fetcher (simulates fast DB read)
export const getProducts = unstable_cache(
  async () => {
    // Read from file (simulating DB)
    return readDB();
  },
  ['products'], 
  { tags: ['products'] } 
);

// Simulate slow external sync
export async function syncProducts() {
    // Simulate slow upstream fetch
    await new Promise((resolve) => setTimeout(resolve, 2000));

    // Read current data
    let currentProducts = readDB();

    // Update local DB with "fresh" data from upstream
    const updatedProducts = currentProducts.map((p: any) => ({
      ...p,
      price: p.price + 10, // Increment price to show change
      stock: Math.floor(Math.random() * 100)
    }));

    writeDB(updatedProducts);

    console.log('Catalog synced from upstream.');

    // Invalidate cache so next read sees new data
    revalidateTag('products');
}

